{
  "operations": [
    {
      "op": "update",
      "collection": "processes",
      "target_id": "PROC_RELAXATION",
      "fields": {
        "scientific_name": "Cessation of ACh-driven signalling, repolarization, SR Ca2+ reuptake and reshielding of actin-binding sites",
        "action_category": "transport",
        "participants": [
          {"role": "signal_source", "entity_ref": "ENT_MOTOR_NEURON_TERMINAL"},
          {"role": "excitable_membrane", "entity_ref": "ENT_SARCOLEMMA_T_TUBULES"},
          {"role": "ca_store", "entity_ref": "ENT_SR"},
          {"role": "regulatory_complex", "entity_ref": "ENT_TROPONIN_TROPOMYOSIN"}
        ],
        "input_roles": ["ca_store", "regulatory_complex"],
        "output_roles": ["ca_store", "regulatory_complex"],
        "preconditions": {
          "motor_neuron_stops_ACh_release": true,
          "ATP_available_for_pumps": true
        },
        "effects": {
          "sarcolemma_repolarized": true,
          "ca_returned_to_SR": true,
          "actin_binding_sites_reshielded": true,
          "muscle_fibre_relaxed": true
        },
        "temporal_scope": {
          "start_condition": "Motor neuron stops releasing ACh",
          "end_condition": "Actin-binding sites reshielded and fibre loses tension",
          "after": ["PROC_CONTRACTION_CROSSBRIDGE_CYCLE"]
        },
        "observables": [
          {
            "constraint_id": "OBS_RELAXATION_REQUIRES_CA_REUPTAKE",
            "predicate": "state_transition_allowed",
            "state_key": "actin_binding_sites",
            "to_value": "reshielded",
            "precondition": {"ca_returned_to_SR": true, "ATP_available_for_pumps": true},
            "capability": "PARTIAL",
            "evidence_ids": ["E_d6fd3723dbb7"],
            "support": [
              {
                "evidence_id": "E_d6fd3723dbb7",
                "quote": "Muscle contraction usually stops when signaling from the motor neuron ends, which repolarizes the sarcolemma and T-tubules, and closes the voltage-gated calcium channels in the SR. Ca ++ ions are then pumped back into the SR, which causes the tropomyosin to reshield (or re-cover) the binding sites on the actin strands.",
                "location": "paragraph_3"
              }
            ]
          },
          {
            "constraint_id": "OBS_RELAXATION_FOLLOWS_CONTRACTION",
            "predicate": "event_precedes",
            "ordered_process_ids": ["PROC_CONTRACTION_CROSSBRIDGE_CYCLE", "PROC_RELAXATION"],
            "capability": "PARTIAL",
            "evidence_ids": ["E_d6fd3723dbb7"],
            "support": [
              {
                "evidence_id": "E_d6fd3723dbb7",
                "quote": "Relaxing skeletal muscle fibers, and ultimately, the skeletal muscle, begins with the motor neuron, which stops releasing its chemical signal, ACh, into the synapse at the NMJ.",
                "location": "paragraph_26"
              }
            ]
          }
        ],
        "evidence_ids": ["E_d6fd3723dbb7"],
        "support": [
          {
            "evidence_id": "E_d6fd3723dbb7",
            "quote": "Muscle contraction usually stops when signaling from the motor neuron ends, which repolarizes the sarcolemma and T-tubules, and closes the voltage-gated calcium channels in the SR.",
            "location": "paragraph_3"
          },
          {
            "evidence_id": "E_d6fd3723dbb7",
            "quote": "ATP-driven pumps will move Ca ++ out of the sarcoplasm back into the SR. This results in the “reshielding” of the actin-binding sites on the thin filaments. Without the ability to form cross-bridges between the thin and thick filaments, the muscle fiber loses its tension and relaxes.",
            "location": "paragraph_26"
          }
        ],
        "exceptions": [
          {
            "description": "A muscle may also stop contracting when it runs out of ATP and becomes fatigued; this ATP-depletion route is not modelled here as normal relaxation.",
            "evidence_quote": "A muscle also can stop contracting when it runs out of ATP and becomes fatigued ( Figure 10.9 ).",
            "location": "paragraph_3"
          }
        ],
        "precondition_state_refs": ["ST_SARCOMERE_SHORTENED", "ST_ATP_AVAILABLE"],
        "effect_state_refs": ["ST_SARCOLEMMA_REPOLARIZED", "ST_CA_RETURNED_TO_SR", "ST_ACTIN_SITES_SHIELDED", "ST_FIBRE_RELAXED"],
        "terminates_state_refs": ["ST_SARCOMERE_SHORTENED", "ST_ACTIN_SITES_UNSHIELDED", "ST_CA_IN_SARCOPLASM"]
      }
    },
    {
      "op": "update",
      "collection": "relations",
      "target_id": "REL_NEURON_TO_SARCOLEMMA",
      "fields": {
        "scientific_name": "Motor neuron ACh signalling to sarcolemma",
        "definition": "The motor neuron terminal releases ACh which acts on the sarcolemma to initiate depolarization",
        "source_entity": "ENT_MOTOR_NEURON_TERMINAL",
        "target_entity": "ENT_SARCOLEMMA_T_TUBULES",
        "evidence_ids": ["E_d6fd3723dbb7"],
        "support": [
          {
            "evidence_id": "E_d6fd3723dbb7",
            "quote": "The sequence of events that result in the contraction of an individual muscle fiber begins with a signal—the neurotransmitter, ACh—from the motor neuron innervating that fiber.",
            "location": "paragraph_1"
          }
        ]
      }
    },
    {
      "op": "update",
      "collection": "relations",
      "target_id": "REL_SARCOLEMMA_TO_SR",
      "fields": {
        "scientific_name": "Sarcolemma/T-tubule depolarization triggers SR Ca2+ release",
        "definition": "Depolarization of the sarcolemma and T-tubules triggers Ca2+ release from the SR into the sarcoplasm",
        "source_entity": "ENT_SARCOLEMMA_T_TUBULES",
        "target_entity": "ENT_SR",
        "evidence_ids": ["E_d6fd3723dbb7"],
        "support": [
          {
            "evidence_id": "E_d6fd3723dbb7",
            "quote": "This triggers the release of calcium ions (Ca ++ ) from storage in the sarcoplasmic reticulum (SR).",
            "location": "paragraph_1"
          }
        ]
      }
    },
    {
      "op": "update",
      "collection": "relations",
      "target_id": "REL_CA_TO_TROPONIN_TROPOMYOSIN",
      "fields": {
        "scientific_name": "Ca2+ binding to troponin unshields actin-binding sites",
        "definition": "Ca2+ binds troponin causing tropomyosin to slide away and expose myosin-binding sites on actin",
        "source_entity": "ENT_SR",
        "target_entity": "ENT_TROPONIN_TROPOMYOSIN",
        "evidence_ids": ["E_d6fd3723dbb7"],
        "support": [
          {
            "evidence_id": "E_d6fd3723dbb7",
            "quote": "The first step in the process of contraction is for Ca ++ to bind to troponin so that tropomyosin can slide away from the binding sites on the actin strands.",
            "location": "paragraph_11"
          }
        ]
      }
    },
    {
      "op": "update",
      "collection": "processes",
      "target_id": "PROC_CA_RELEASE_AND_TROPONIN_BINDING",
