        "input_roles": ["trigger_membrane", "ca_store"],
        "output_roles": ["ca_store", "ca_sensor"],
        "preconditions": {"t_tubules_depolarized": true, "SR_contains_Ca2+": true},
        "effects": {"ca_in_sarcoplasm": true, "actin_binding_sites_unshielded": true},
        "temporal_scope": {
          "start_condition": "T-tubule depolarization reaches SR",
          "end_condition": "Ca2+ bound to troponin and tropomyosin has slid away from actin-binding sites",
          "after": ["PROC_EXCITATION"]
        },
        "observables": [
          {
            "constraint_id": "OBS_CA_RELEASE_REQUIRES_DEPOLARIZATION",
            "predicate": "event_precedes",
            "ordered_process_ids": ["PROC_EXCITATION", "PROC_CA_RELEASE_AND_TROPONIN_BINDING"],
            "capability": "PARTIAL",
            "evidence_ids": ["E_d6fd3723dbb7"],
            "support": [
              {
                "evidence_id": "E_d6fd3723dbb7",
                "quote": "This triggers the release of calcium ions (Ca ++ ) from storage in the sarcoplasmic reticulum (SR).",
                "location": "paragraph_1"
              }
            ]
          },
          {
            "constraint_id": "OBS_SITE_UNSHIELDING",
            "predicate": "state_transition_allowed",
            "state_key": "actin_binding_sites",
            "to_value": "unshielded",
            "precondition": {"ca_bound_to_troponin": true},
            "capability": "PARTIAL",
            "evidence_ids": ["E_d6fd3723dbb7"],
            "support": [
              {
                "evidence_id": "E_d6fd3723dbb7",
                "quote": "The first step in the process of contraction is for Ca ++ to bind to troponin so that tropomyosin can slide away from the binding sites on the actin strands.",
                "location": "paragraph_11"
              }
            ]
          }
        ],
        "evidence_ids": ["E_d6fd3723dbb7"],
        "support": [
          {
            "evidence_id": "E_d6fd3723dbb7",
            "quote": "This triggers the release of calcium ions (Ca ++ ) from storage in the sarcoplasmic reticulum (SR).",
            "location": "paragraph_1"
          },
          {
            "evidence_id": "E_d6fd3723dbb7",
            "quote": "The first step in the process of contraction is for Ca ++ to bind to troponin so that tropomyosin can slide away from the binding sites on the actin strands.",
            "location": "paragraph_11"
          }
        ],
        "exceptions": [],
        "precondition_state_refs": ["ST_SARCOLEMMA_DEPOLARIZED"],
        "effect_state_refs": ["ST_CA_IN_SARCOPLASM", "ST_ACTIN_SITES_UNSHIELDED"],
        "terminates_state_refs": ["ST_ACTIN_SITES_SHIELDED"]
      }
    },
    {
      "op": "update",
      "collection": "processes",
      "target_id": "PROC_CONTRACTION_CROSSBRIDGE_CYCLE",
      "fields": {
        "scientific_name": "ATP-dependent cross-bridge cycling and thin-filament sliding",
        "action_category": "interaction",
        "participants": [
          {"role": "contractile_filaments", "entity_ref": "ENT_ACTIN_MYOSIN_SARCOMERE"},
          {"role": "regulatory_complex", "entity_ref": "ENT_TROPONIN_TROPOMYOSIN"}
        ],
        "input_roles": ["regulatory_complex", "contractile_filaments"],
        "output_roles": ["contractile_filaments"],
        "preconditions": {"actin_binding_sites_unshielded": true, "ca_in_sarcoplasm": true, "ATP_available": true},
        "effects": {"sarcomere_shortened": true, "muscle_fibre_tension": true},
        "temporal_scope": {
          "start_condition": "Actin-binding sites exposed and ATP available",
          "end_condition": "Ca2+ removed or ATP depleted (contraction ceases)",
          "after": ["PROC_CA_RELEASE_AND_TROPONIN_BINDING"]
        },
        "observables": [
          {
            "constraint_id": "OBS_CONTRACTION_REQUIRES_CA_AND_ATP",
            "predicate": "relation_holds_during",
            "relation_ref": "REL_CROSSBRIDGE_ACTIN_MYOSIN",
            "source_role": "contractile_filaments",
            "target_role": "contractile_filaments",
            "capability": "PARTIAL",
            "evidence_ids": ["E_d6fd3723dbb7"],
            "support": [
              {
                "evidence_id": "E_d6fd3723dbb7",
                "quote": "As long as Ca ++ ions remain in the sarcoplasm to bind to troponin, which keeps the actin-binding sites “unshielded,” and as long as ATP is available to drive the cross-bridge cycling and the pulling of actin strands by myosin, the muscle fiber will continue to shorten to an anatomical limit.",
                "location": "paragraph_1"
              }
            ]
          }
        ],
        "evidence_ids": ["E_d6fd3723dbb7"],
        "support": [
          {
            "evidence_id": "E_d6fd3723dbb7",
            "quote": "This allows the myosin heads to bind to these exposed binding sites and form cross-bridges. The thin filaments are then pulled by the myosin heads to slide past the thick filaments toward the center of the sarcomere.",
            "location": "paragraph_11"
          },
          {
            "evidence_id": "E_d6fd3723dbb7",
            "quote": "ATP binding causes the myosin head to detach from the actin ( Figure 10.11 d ). After this occurs, ATP is converted to ADP and P i by the intrinsic ATPase activity of myosin.",
            "location": "paragraph_15"
          }
        ],
        "exceptions": [
          {
            "description": "If ATP runs out, myosin heads cannot detach from actin and the muscle cannot relax normally (rigor).",
            "evidence_quote": "In the absence of ATP, the myosin head will not detach from actin.",
            "location": "paragraph_14"
          }
        ],
        "precondition_state_refs": ["ST_CA_IN_SARCOPLASM", "ST_ACTIN_SITES_UNSHIELDED", "ST_ATP_AVAILABLE"],
        "effect_state_refs": ["ST_SARCOMERE_SHORTENED"],
        "terminates_state_refs": []
      }
    }
  ],
